<div x-data="galleryUpload" class="space-y-4"><label class="block rounded-xl border border-dashed border-slate-300 p-4 dark:border-slate-600" @dragover.prevent @drop.prevent="drop($event)"><span class="text-sm font-semibold">Chọn hoặc kéo ảnh vào đây</span><input x-ref="files" type="file" name="gallery[]" multiple accept="image/jpeg,image/png,image/webp" class="app-input mt-2" @change="select($event)"><span class="mt-2 block text-xs leading-5 text-slate-500">JPG, PNG, WebP; mỗi ảnh tối đa 4 MB. Tối đa {{ config('housing.max_images') }} ảnh. Có thể đổi thứ tự ảnh trước khi lưu.</span></label><div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="(photo,index) in photos" :key="photo.url"><div class="min-w-0"><img :src="photo.url" :alt="'Ảnh mới ' + (index+1)" class="aspect-[4/3] w-full rounded-xl object-cover"><div class="mt-2 flex justify-between gap-1"><button type="button" class="app-button-muted px-2" @click="move(index,-1)" :disabled="index===0" aria-label="Đưa ảnh lên trước">←</button><button type="button" class="app-button-muted px-2" @click="remove(index)" aria-label="Bỏ ảnh">×</button><button type="button" class="app-button-muted px-2" @click="move(index,1)" :disabled="index===photos.length-1" aria-label="Đưa ảnh về sau">→</button></div></div></template></div>@if($field['options'])<fieldset><legend class="mb-3 text-sm font-semibold">Ảnh đã lưu</legend><div class="grid grid-cols-2 gap-3 sm:grid-cols-3">@foreach($field['options'] as $mediaId=>$url)<label class="min-w-0"><img src="{{ $url }}" alt="Ảnh đã lưu" class="aspect-[4/3] w-full rounded-xl object-cover"><span class="mt-2 flex gap-2 text-sm"><input type="checkbox" name="remove_images[]" value="{{ $mediaId }}">Xóa ảnh này</span></label>@endforeach</div></fieldset>@endif</div>
